/// 📚 90-Day Progressive Vocabulary Curriculum
/// Designed specifically for English learners:
/// - Days 1–20: Tier 1 (Super Simple Everyday Conversational Words)
/// - Days 21–45: Tier 2 (Pre-Intermediate Communication, Descriptions, Work & Life)
/// - Days 46–70: Tier 3 (Intermediate Fluency, Professional English, Discussions)
/// - Days 71–90: Tier 4 (Advanced Mastery, Eloquence, Leadership & Nuance)
class Pocket90DayVocabCurriculum {
  /// Returns the 10 tailored, 100% unique vocabulary items for any day (1 to 90)
  static List<DailyVocabItem> getVocabForDay(int day) {
    if (day < 1) day = 1;
    if (day > 90) day = 90;

    // Check pre-compiled master curriculum
    final items = _curriculum[day];
    if (items != null && items.isNotEmpty) {
      return items;
    }

    return _curriculum[1] ?? const [];
  }

